const cars=[
 {id:'compact',name:'Fiat 500',category:'Economy',description:'Small footprint. Big possibilities.',price:35,seats:4,doors:3,bags:1,gear:'Automatic',fuel:'Petrol',image:'images/car-0.jpg'},
 {id:'corolla',name:'Toyota Corolla',category:'Sedan',description:'An easy-going everyday companion.',price:49,seats:5,doors:4,bags:3,gear:'Automatic',fuel:'Petrol',image:'images/car-1.jpg'},
 {id:'sorento',name:'Ford Edge',category:'SUV',description:'More room for the whole adventure.',price:79,seats:5,doors:5,bags:4,gear:'Automatic',fuel:'Diesel',image:'images/car-2.jpg'},
 {id:'bmw',name:'BMW 3 Series',category:'Luxury',description:'Make the journey the destination.',price:99,seats:5,doors:4,bags:3,gear:'Automatic',fuel:'Petrol',image:'images/car-3.jpg'},
 {id:'convertible',name:'Ford Mustang Convertible',category:'Convertible',description:'Open skies. A fresh perspective.',price:119,seats:4,doors:2,bags:2,gear:'Automatic',fuel:'Petrol',image:'images/car-4.jpg'},
 {id:'van',name:'Volkswagen Transporter',category:'Van',description:'Extra space for your bigger plans.',price:89,seats:3,doors:4,bags:8,gear:'Manual',fuel:'Diesel',image:'images/car-5.jpg'}
];
const categories=['All cars','Economy','Sedan','SUV','Luxury','Convertible','Van'];let category='All cars';let selected=null;
const $=id=>document.getElementById(id);const today=new Date();today.setMinutes(today.getMinutes()-today.getTimezoneOffset());const tomorrow=new Date(today);tomorrow.setDate(today.getDate()+3);$('pickup').value=today.toISOString().slice(0,10);$('pickup').min=$('pickup').value;$('dropoff').value=tomorrow.toISOString().slice(0,10);$('dropoff').min=$('pickup').value;
const paths={seats:'M8 10a3 3 0 1 0 0-6 3 3 0 0 0 0 6Zm-5 9v-3a5 5 0 0 1 10 0v3m3-14a3 3 0 0 1 0 6m1 3a4 4 0 0 1 4 4v1',doors:'M4 21V9l6-6h10v18H4Zm1-11h14M14 14h3',bags:'M8 6V3h8v3M5 6h14v14H5V6Zm3 0v14m8-14v14',gear:'M6 3v18M6 12h12V3M18 12v9M3 3h6M15 3h6M3 21h6M15 21h6'};
const icon=k=>`<svg viewBox="0 0 24 24" aria-hidden="true"><path d="${paths[k]}"/></svg>`;
const specs=c=>`<div class="specs"><span>${icon('seats')}${c.seats} seats</span><span>${icon('doors')}${c.doors} doors</span><span>${icon('bags')}${c.bags} bags</span><span>${icon('gear')}${c.gear}</span></div>`;
function filtered(){let result=cars.filter(c=>category==='All cars'||c.category===category);if($('sort').value==='low')result.sort((a,b)=>a.price-b.price);if($('sort').value==='high')result.sort((a,b)=>b.price-a.price);if($('sort').value==='seats')result.sort((a,b)=>b.seats-a.seats);return result;}
function render(){ $('categories').innerHTML=categories.map(c=>`<button type="button" class="category ${category===c?'active':''}" aria-pressed="${category===c}" data-category="${c}">${c}</button>`).join('');const result=filtered();$('result-count').textContent=`${result.length} ${result.length===1?'vehicle':'vehicles'} · Daily rates in USD`;$('car-grid').innerHTML=result.map(c=>`<article class="car-card"><div class="car-image"><img src="${c.image}" alt="${c.name}" loading="lazy"><span class="tag">${c.category}</span></div><div class="car-info"><h3>${c.name}</h3><p class="sub">${c.description}</p>${specs(c)}<div class="card-bottom"><span class="price">$${c.price} <small>/ day</small></span><button class="detail-button" data-car="${c.id}">View details ↗</button></div></div></article>`).join('');}
function datesValid(){const start=$('pickup').value,end=$('dropoff').value;let error='';if(!start||!end)error='Choose both a pick-up and return date.';else if(start<today.toISOString().slice(0,10))error='Choose a pick-up date from today onwards.';else if(end<=start)error='Your return date must be after your pick-up date.';$('date-error').textContent=error;return !error;}
function days(){return Math.round((Date.parse($('dropoff').value)-Date.parse($('pickup').value))/86400000);}
function showDetails(id){const c=cars.find(c=>c.id===id);if(!c)throw new Error('Unknown vehicle');selected=c;const valid=datesValid();const count=valid?days():0;$('details').innerHTML=`<img class="detail-photo" src="${c.image}" alt="${c.name}"><div class="detail-body"><p class="eyebrow">${c.category} · ${c.fuel}</p><h2 id="detail-title">${c.name}</h2><p>${c.description}</p>${specs(c)}<p class="detail-note">${c.bags} standard suitcases with all seats in use. Vehicle and luggage specifications are illustrative; the supplied variant may differ.</p><div class="estimate"><div>${valid?`${count} day${count===1?'':'s'} × $${c.price}<br><small>Estimated rental total</small>`:`Daily rental rate`}</div><strong>$${valid?count*c.price:c.price}</strong></div><p class="detail-note">${valid?`${$('pickup').value} to ${$('dropoff').value} · ${$('location').value}`:'Select valid rental dates to calculate your trip total.'}</p><p class="detail-note">This is a rental preview, not a confirmed reservation. Taxes, insurance, deposits and any additional fees are not included. No payment or booking is submitted.</p><button class="button" id="edit-dates">${valid?'Change trip dates':'Choose trip dates'} <span>↗</span></button></div>`;if(!$('car-dialog').open)$('car-dialog').showModal();$('edit-dates').onclick=()=>{$('car-dialog').close();$('search').scrollIntoView();$('pickup').focus({preventScroll:true});};}
$('categories').addEventListener('click',e=>{const b=e.target.closest('[data-category]');if(b){category=b.dataset.category;render();}});$('sort').onchange=render;$('car-grid').addEventListener('click',e=>{const b=e.target.closest('[data-car]');if(b)showDetails(b.dataset.car);});$('close-dialog').onclick=()=>$('car-dialog').close();$('car-dialog').addEventListener('click',e=>{if(e.target===$('car-dialog')){const r=e.target.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)e.target.close();}});$('pickup').onchange=()=>{$('dropoff').min=$('pickup').value;};$('search-form').onsubmit=e=>{e.preventDefault();if(datesValid()){$('fleet').scrollIntoView();render();$('result-count').textContent+=` · ${days()}-day rental from ${$('location').value}`;}};render();

if(document.modelContext?.registerTool){try{Promise.resolve(document.modelContext.registerTool({name:'filter_vehicle_category',description:'Filter the visible preview fleet by vehicle category.',inputSchema:{type:'object',properties:{category:{type:'string',enum:categories}},required:['category'],additionalProperties:false},annotations:{readOnlyHint:false,untrustedContentHint:false},execute(input){if(!input||!categories.includes(input.category))throw new Error('Choose a listed vehicle category');category=input.category;render();return {category,vehicles:filtered().map(({id,name,price,seats,doors,bags})=>({id,name,price,seats,doors,bags}))}}})).catch(()=>{});}catch{}}
